Here is the commit message:
EDAC/versalnet: Fix device_node leak in mc_probe()

of_parse_phandle() returns a device_node reference that must be released with
of_node_put(). The original code never freed r5_core_node on any exit path,
causing a memory leak.

Fix this by using the automatic cleanup attribute __free(device_node) which
ensures of_node_put() is called when the variable goes out of scope.

Fixes: d5fe2fec6c40 ("EDAC: Add a driver for the AMD Versal NET DDR controller")
Signed-off-by: Felix Gu <ustc.gu@gmail.com>
Signed-off-by: Borislav Petkov (AMD) <bp@alien8.de>
Reviewed-by: Shubhrajyoti Datta <shubhrajyoti.datta@amd.com>
Cc: <stable@kernel.org>
Link: https://patch.msgid.link/20260323-versalnet-v1-1-4ab3012635ef@gmail.com

Here is the root cause:
The function mc_probe() calls of_parse_phandle() to obtain a device_node reference but never releases it via of_node_put() on any return path, causing a memory leak.

Here is the patch:

 static int mc_probe(struct platform_device *pdev)
 {
-	struct device_node *r5_core_node;
 	struct mc_priv *priv;
 	struct rproc *rp;
 	int rc;

-	r5_core_node = of_parse_phandle(pdev->dev.of_node, "amd,rproc", 0);
+	struct device_node *r5_core_node __free(device_node) =
+		of_parse_phandle(pdev->dev.of_node, "amd,rproc", 0);
 	if (!r5_core_node) {
 		dev_err(&pdev->dev, "amd,rproc: invalid phandle\n");
 		return -EINVAL;
 	}

 	rp = rproc_get_by_phandle(r5_core_node->phandle);
 	if (!rp)
 		return -EPROBE_DEFER;

 	rc = rproc_boot(rp);
 	if (rc) {
 		dev_err(&pdev->dev, "Failed to attach to remote processor\n");
 		goto err_rproc_boot;
 	}

 	priv = devm_kzalloc(&pdev->dev, sizeof(*priv), GFP_KERNEL);
 	if (!priv) {
 		rc = -ENOMEM;
 		goto err_alloc;
 	}

 	amd_rpmsg_id_table[0].driver_data = (kernel_ulong_t)priv;

 	rc = register_rpmsg_driver(&amd_rpmsg_driver);
 	if (rc) {
 		edac_printk(KERN_ERR, EDAC_MC, "Failed to register RPMsg driver: %d\n", rc);
 		goto err_alloc;
 	}

 	rc = setup_mcdi(priv);
 	if (rc)
 		goto err_unreg;

 	priv->mcdi->r5_rproc = rp;

 	rc = init_versalnet(priv, pdev);
 	if (rc)
 		goto err_init;

 	return 0;

 err_init:
 	cdx_mcdi_finish(priv->mcdi);
 	kfree(priv->mcdi);

 err_unreg:
 	unregister_rpmsg_driver(&amd_rpmsg_driver);

 err_alloc:
 	rproc_shutdown(rp);

 err_rproc_boot:
 	rproc_put(rp);

 	return rc;
 }



